# --------------------------------------------------------------------------
# expressions and templates
# --------------------------------------------------------------------------

class ExpressionError(ValueError):
    pass


def ast_depth(body):
    """Maximum AST child-edge depth, root body counted as depth 0."""
    best = 0
    stack = [(body, 0)]
    while stack:
        node, depth = stack.pop()
        if depth > best:
            best = depth
        for child in ast.iter_child_nodes(node):
            stack.append((child, depth + 1))
    return best


class Context:
    """Definition environment plus template compilation for one document."""

    def __init__(self, definitions, seed):
        self.seed = seed
        self.definitions = definitions
        self.env = {}
        self.cache = {}
        for name, source in definitions:
            if not IDENT.fullmatch(name) or keyword.iskeyword(name):
                raise ExpressionError('definition name')
            if name in self.env:
                raise ExpressionError('duplicate definition')
            self.env[name] = self.expression(source)

    # -- expressions ------------------------------------------------------
    def expression(self, source):
        if len(source) > 8192:
            raise ExpressionError('expression source budget')
        cached = self.cache.get(source)
        if cached is not None:
            return cached
        result = self._compile(source)
        if len(self.cache) < 65536:
            self.cache[source] = result
        return result

    def _compile(self, source):
        try:
            tree = ast.parse(source, mode='eval')
        except (SyntaxError, ValueError, RecursionError, MemoryError):
            raise ExpressionError('expression syntax') from None
        body = tree.body
        if ast_depth(body) > 128:
            raise ExpressionError('expression depth')
        value = self._eval(body)
        if not isinstance(value, Node):
            raise ExpressionError('expression must be bytes')
        return value

    def _eval(self, node):
        kind = type(node)
        if kind is ast.Constant:
            value = node.value
            if type(value) is bytes:
                return literal(value)
            if type(value) is str:
                return literal(value.encode('utf8'))
            if type(value) is int:
                if value < 0 or value > MAX:
                    raise ExpressionError('integer literal range')
                return value
            raise ExpressionError('constant type')
        if kind is ast.Name:
            try:
                return self.env[node.id]
            except KeyError:
                raise ExpressionError('unknown name') from None
        if kind is ast.BinOp:
            op = type(node.op)
            left = self._eval(node.left)
            right = self._eval(node.right)
            if op is ast.Add:
                if not isinstance(left, Node) or not isinstance(right, Node):
                    raise ExpressionError('concat operands')
                return cat((left, right))
            if op is ast.Mult:
                if isinstance(left, Node) and type(right) is int:
                    return repeat(left, right)
                if isinstance(right, Node) and type(left) is int:
                    return repeat(right, left)
                raise ExpressionError('repeat operands')
            raise ExpressionError('operator')
        if kind is ast.Subscript:
            target = self._eval(node.value)
            if not isinstance(target, Node):
                raise ExpressionError('slice operand')
            selector = node.slice
            if type(selector) is not ast.Slice:
                raise ExpressionError('slice form')
            if selector.step is not None:
                raise ExpressionError('slice step')
            lo = 0 if selector.lower is None else self._index(selector.lower)
            hi = target.n if selector.upper is None else self._index(selector.upper)
            if not 0 <= lo <= hi <= target.n:
                raise ExpressionError('slice range')
            return cut(target, lo, hi)
        raise ExpressionError('syntax %s' % kind.__name__)

    def _index(self, node):
        if type(node) is not ast.Constant or type(node.value) is not int:
            raise ExpressionError('slice endpoint')
        value = node.value
        if value < 0 or value > MAX:
            raise ExpressionError('slice endpoint range')
        return value

    # -- templates --------------------------------------------------------
    def template(self, value, coordinate):
        if type(value) is not str:
            raise ExpressionError('template type')
        if value.startswith('{{') and value.endswith('}}'):
            return self.expression(value[2:-2].strip())
        if value.find(RANDOM_TOKEN) < 0:
            return literal(value.encode('utf8'))
        pieces = []
        index = 0
        occurrence = 0
        span = len(RANDOM_TOKEN)
        while True:
            found = value.find(RANDOM_TOKEN, index)
            if found < 0:
                pieces.append(value[index:])
                break
            pieces.append(value[index:found])
            digest = hashlib.sha256(
                ('%s/%s/%d' % (self.seed, coordinate, occurrence)).encode('utf8')
            ).hexdigest()[:20]
            pieces.append(digest)
            index = found + span
            occurrence += 1
        return literal(''.join(pieces).encode('utf8'))
